"""Expanded ticker universe: S&P 500 + S&P 400 (mid-cap) + S&P 600 (small-cap),scraped from Wikipedia the same way sp500Tickers() already does.This is deliberately NOT a random sample of all yfinance-tradeable tickers,that would pull in illiquid, noisy names (penny stocks, thin ADRs, etc.)that hurt signal-to-noise more than more training rows helps. This insteadwidens the SAME kind of well-defined, reasonably-vetted universe youalready had, just bigger, roughly 500 -> ~1,400-1,500 tickers."""import requestsimport pandas as pdimport iodef _scrape_wikipedia_symbol_table(url: str, table_index: int = 0, symbol_col: str = 'Symbol'):    headers = {"User-Agent": "Mozilla/5.0"}    response = requests.get(url, headers=headers)    tables = pd.read_html(io.BytesIO(response.content))    relevant = tables[table_index]    symbols = relevant[symbol_col]    # yfinance wants BRK-B, not BRK.B    return symbols.str.replace('.', '-', regex=False)def sp400Tickers():    url = "https://en.wikipedia.org/wiki/List_of_S%26P_400_companies"    return _scrape_wikipedia_symbol_table(url)def sp600Tickers():    url = "https://en.wikipedia.org/wiki/List_of_S%26P_600_companies"    return _scrape_wikipedia_symbol_table(url)def expandedTickerUniverse():    """    Returns a deduplicated list combining S&P 500 + S&P 400 + S&P 600.    Import sp500Tickers from your existing data_loading module.    """    from src.data_loading import sp500Tickers    sp500 = sp500Tickers()    sp400 = sp400Tickers()    sp600 = sp600Tickers()    combined = pd.concat([sp500, sp400, sp600]).drop_duplicates().reset_index(drop=True)    print(f"Expanded universe: {len(sp500)} (S&P 500) + {len(sp400)} (S&P 400) "          f"+ {len(sp600)} (S&P 600) = {len(combined)} unique tickers")    return combined